-- Equalizer schema v14: adds 5 original "which transformation sequence maps
-- this shape onto that one" questions (grid diagram, before -> after),
-- matching the TJ/ACL-style composite-transformation question type. Every
-- correct answer and every wrong answer was computed programmatically
-- (rotation/reflection/translation formulas applied to the shape's actual
-- vertex coordinates, not eyeballed) and each diagram was rendered from
-- those same coordinates, so the pictured shapes and the text answers are
-- guaranteed to agree. Written from scratch, not copied from any source.
--
-- To keep the total question count unchanged, deletes 5 more rows from
-- the "warehouse cube blocks" template (see migrations_v13.sql, which
-- already removed 2 of these 35 near-identical duplicates) -- 33 remain
-- before this migration, 28 after, still a large number of variants.

delete from public.questions where id in (230, 239, 240, 245, 246);

insert into public.questions (subject, category, question, options, answer_index, explanation, diagram_svg) values

('acl', 'Spatial/Geometric', 'What set of transformations will transform the leftmost image into the rightmost image?',
